\begin{proof}
\textbf{Theorem (Jensen).}
Let $f:\mathbb R\to\mathbb R$ be convex. Let $x_1,\dots,x_n\in\mathbb R$ and $\lambda_1,\dots,\lambda_n\ge0$ with $\displaystyle\sum_{i=1}^{n}\lambda_i=1$. Then
\[
f\!\Bigl(\sum_{i=1}^{n}\lambda_i x_i\Bigr)\le\sum_{i=1}^{n}\lambda_i f(x_i).\tag{J}
\]

\medskip
\textbf{1. Trivial cases.}
\begin{itemize}
\item $n=1$: $\lambda_1=1$ and (J) reads $f(x_1)\le f(x_1)$.
\item A single weight equal to $1$: if $\lambda_k=1$ and $\lambda_i=0$ for $i\neq k$, then both sides of (J) equal $f(x_k)$.
\end{itemize}

\textbf{2. Reduction of zero weights.}
If some $\lambda_j=0$ we may delete the index $j$; the hypothesis $\sum\lambda_i=1$ and (J) are unchanged. Hence we may assume all listed weights are non‑negative (zero allowed).

\textbf{3. Base case $n=2$ (binary Jensen).}
Convexity gives, for $t\in[0,1]$ and $x,y\in\mathbb R$,
\begin{align*}
f\bigl(t x+(1-t)y\bigr)\le t\,f(x)+(1-t)\,f(y). \tag{1}
\end{align*}
Choosing $t=\lambda_1$, $1-t=\lambda_2$ (so $\lambda_1+\lambda_2=1$) yields
\begin{align*}
f(\lambda_1x_1+\lambda_2x_2)\le\lambda_1f(x_1)+\lambda_2f(x_2). \tag{2}
\end{align*}
Thus (J) holds for $n=2$.

\textbf{4. Inductive step.}
Assume (J) holds for any collection of $n$ points with non‑negative weights summing to $1$. Let $\lambda_1,\dots,\lambda_{n+1}\ge0$ with $\displaystyle\sum_{i=1}^{n+1}\lambda_i=1$. Set
\begin{align*}
\mu:=\sum_{i=1}^{n}\lambda_i = 1-\lambda_{n+1}. \tag{3}
\end{align*}
If $\mu=0$ then $\lambda_{n+1}=1$ and we are in the trivial case; hence we may suppose $\mu>0$.
Define
\begin{align*}
y:=\frac{1}{\mu}\sum_{i=1}^{n}\lambda_i x_i . \tag{4}
\end{align*}
Then $\alpha_i:=\lambda_i/\mu\;(i=1,\dots,n)$ satisfy $\alpha_i\ge0$ and $\displaystyle\sum_{i=1}^{n}\alpha_i=1$.
A direct computation gives
\begin{align*}
\mu y+\lambda_{n+1}x_{n+1}
   = \sum_{i=1}^{n}\lambda_i x_i+\lambda_{n+1}x_{n+1}
   = \sum_{i=1}^{n+1}\lambda_i x_i . \tag{5}
\end{align*}
Apply the binary convexity inequality (2) to the pair $(y,x_{n+1})$ with weights $\mu$ and $\lambda_{n+1}$:
\begin{align*}
f(\mu y+\lambda_{n+1}x_{n+1})
   \le \mu f(y)+\lambda_{n+1}f(x_{n+1}). \tag{6}
\end{align*}
By the induction hypothesis applied to $x_1,\dots,x_n$ with weights $\alpha_i$,
\begin{align*}
f(y)=f\!\Bigl(\sum_{i=1}^{n}\alpha_i x_i\Bigr)
     \le \sum_{i=1}^{n}\alpha_i f(x_i)
     = \frac{1}{\mu}\sum_{i=1}^{n}\lambda_i f(x_i). \tag{7}
\end{align*}
Multiplying (7) by $\mu$ yields
\begin{align*}
\mu f(y)\le\sum_{i=1}^{n}\lambda_i f(x_i). \tag{8}
\end{align*}
Insert (8) into (6) and use (5):
\begin{align*}
f\!\Bigl(\sum_{i=1}^{n+1}\lambda_i x_i\Bigr)
   \le \sum_{i=1}^{n}\lambda_i f(x_i)+\lambda_{n+1}f(x_{n+1})
   = \sum_{i=1}^{n+1}\lambda_i f(x_i). \tag{9}
\end{align*}
Thus (J) holds for $n+1$ points, and by induction for every $n\ge1$.

\textbf{5. Equality case.}
From the binary case we know that equality in (2) occurs exactly when either $\lambda_1\in\{0,1\}$ (the combination reduces to a single point) or $f$ is affine on the segment $[x_1,x_2]$ (equivalently $x_1=x_2$ when $f$ is strictly convex). In the inductive argument, equality in (9) requires equality in both the binary step (6) and the induction hypothesis (7). Consequently, equality in (J) holds precisely when one of the following holds:
\begin{enumerate}
\item There exists $k$ with $\lambda_k=1$ (all other weights are zero);
\item The restriction of $f$ to the convex hull of $\{x_i:\lambda_i>0\}$ is affine. In particular, if $f$ is strictly convex, this forces all points with positive weight to coincide.
\end{enumerate}

\textbf{6. Conclusion.}
For any convex $f$, any real numbers $x_1,\dots,x_n$, and any non‑negative weights $\lambda_1,\dots,\lambda_n$ with $\displaystyle\sum_{i=1}^{n}\lambda_i=1$, Jensen’s inequality
\[
f\!\Bigl(\sum_{i=1}^{n}\lambda_i x_i\Bigr)\le\sum_{i=1}^{n}\lambda_i f(x_i)
\]
holds, with equality exactly in the situations described above. \qed
\end{proof}
